<?php require '../config/auth.php';login_required('student');$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT j.*,c.company_name,c.description company_description,c.logo FROM jobs j JOIN companies c ON c.id=j.company_id WHERE j.id=? AND j.status='approved'");$q->execute([$id]);$j=$q->fetch();if(!$j)go('jobs.php');$q=$pdo->prepare('SELECT a.* FROM applications a JOIN students s ON s.id=a.student_id WHERE a.job_id=? AND s.user_id=?');$q->execute([$id,$_SESSION['user_id']]);$existing=$q->fetch();$q=$pdo->prepare('SELECT * FROM students WHERE user_id=?');$q->execute([$_SESSION['user_id']]);$s=$q->fetch();$eligible=(float)($s['cgpa']??0)>=(float)$j['min_cgpa'];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(!$eligible)flash('You do not meet the minimum CGPA requirement.','error');elseif(!$s['resume'])flash('Upload your resume before applying.','error');elseif($existing)flash('Duplicate application prevented.','error');else{$pdo->prepare("INSERT INTO applications(job_id,student_id,status) VALUES(?,?, 'applied')")->execute([$id,$s['id']]);notify($_SESSION['user_id'],'Application submitted','Your application for '.$j['job_title'].' at '.$j['company_name'].' was submitted.');flash('Application submitted successfully.');}go('job-details.php?id='.$id);}$page_title=$j['job_title'];require '../config/header.php';flashes();?><div class="head"><div><h1><?=e($j['job_title'])?></h1><p><?=e($j['company_name'])?> · <?=e($j['location'])?></p></div><a class="btn outline" href="jobs.php">← Jobs</a></div><div class="grid g2"><div class="card"><h2><?=e($j['job_title'])?></h2><p class="muted"><?=nl2br(e($j['description']))?></p><h3>Responsibilities</h3><p class="muted"><?=nl2br(e($j['responsibilities']))?></p><h3>Required Skills</h3><div class="chips"><?php foreach(explode(',',$j['required_skills']) as $sk):?><span class="chip"><?=e(trim($sk))?></span><?php endforeach;?></div><h3>Selection Process</h3><p class="muted"><?=nl2br(e($j['selection_process']))?></p></div><div><div class="card"><h3>Opportunity Snapshot</h3><div class="meta" style="grid-template-columns:1fr"><span>🎓 Qualification: <?=e($j['qualification'])?></span><span>📈 Minimum CGPA: <?=e($j['min_cgpa'])?></span><span>💰 Package: <?=e($j['package_lpa'])?> LPA</span><span>📅 Deadline: <?=e($j['application_deadline'])?></span><span>💼 Type: <?=e($j['job_type'])?></span></div><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><?php if($existing):?><div class="notice">Application status: <b><?=e($existing['status'])?></b></div><?php elseif(!$eligible):?><div class="flash error">Your CGPA does not meet the eligibility criteria.</div><?php elseif(!$s['resume']):?><div class="flash error">Upload your resume in My Profile.</div><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button class="btn primary" style="width:100%">Confirm Application →</button></form><?php endif;?></div><div class="card" style="margin-top:17px"><h3>About Company</h3><p class="muted"><?=nl2br(e($j['company_description']))?></p></div></div></div><?php require '../config/footer.php';?>
